(function (N) {
  const L = window.LH, EN = window.LANG === "en";
  const tr = s => (typeof window.trS === "function" ? window.trS(s) : s);
  const sp = (o, f) => (EN && o.en && o.en[f] != null && o.en[f] !== "") ? o.en[f] : o[f];
  Object.assign(L.QUELLEN, N.quellen || {});
  if (N.stand) L.STAND = EN ? N.stand.en : N.stand.de;
  L.NEU_LOG = (N.log || []).slice().reverse().map(l => ({ datum: l.datum, version: l.version, punkte: EN ? (l.en || l.de) : l.de }));
  L.NEU_IDS = {};
  /* neue Orte */
  (N.orte || []).forEach(o => {
    const x = Object.assign({}, o); delete x.en; delete x.neu;
    if (EN && o.en) { ["n", "r", "t"].forEach(f => { if (o.en[f]) x[f] = o.en[f]; }); if (x.codes && o.en.c) x.codes = x.codes.map((c, i) => [o.en.c[i] || c[0], c[1]]); }
    if (EN) { if (x.typ) x.typ = tr(x.typ); if (x.geb) x.geb = tr(x.geb); }
    L.ORTE.push(x); L.NEU_IDS[x.id] = o.neu;
  });
  /* Ergänzungen bestehender Orte */
  const I = {}; L.ORTE.forEach(o => { I[o.id] = o; });
  Object.entries(N.ergaenzen || {}).forEach(([id, e]) => {
    const o = I[id]; if (!o) return;
    const x = Object.assign({}, e); delete x.en; delete x.neu;
    if (EN && e.en) ["n", "r", "t"].forEach(f => { if (e.en[f]) x[f] = e.en[f]; });
    if (x.src && o.src) x.src = [...new Set([...o.src, ...x.src])];
    Object.assign(o, x); L.NEU_IDS[id] = e.neu;
  });
  /* Listen */
  (N.tipps || []).forEach(t => { const a = EN && t.en ? [t.en.thema || t.thema, t.en.t || t.t] : [t.thema, t.t]; a.src = t.src || []; a.neu = t.neu; L.TIPPS.push(a); });
  (N.verpassbar || []).forEach(v => L.VERPASSBAR.push({ n: sp(v, "n"), t: sp(v, "t"), at: v.at, neu: v.neu }));
  const GI = {}; L.GLITCHES.forEach(g => { GI[(g.n || "").toLowerCase()] = g; });
  (N.glitches || []).forEach(g => {
    const alt = g.ersetzt && GI[g.ersetzt.toLowerCase()];
    if (alt) { alt.status = g.status; if (g.t) alt.hinweis = sp(g, "t"); alt.neu = g.neu; alt.src = [...new Set([...(alt.src || []), ...(g.src || [])])]; return; }
    L.GLITCHES.push({ n: sp(g, "n"), t: sp(g, "t"), q: g.q || "e", src: g.src || [], at: g.at, status: g.status, neu: g.neu });
  });
  (N.bugs || []).forEach(b => { const a = [sp(b, "n"), tr(b.schwere), b.plattform || "", sp(b, "loesung")]; a.src = b.src; a.neu = b.neu; L.BUGS.push(a); });
  (N.autos || []).forEach(a => L.AUTOS.push({ titel: sp(a, "titel"), text: sp(a, "text"), q: a.q || "e", src: a.src || [], at: a.at, neu: a.neu }));
  (N.lager || []).forEach(a => L.LAGER.push({ titel: sp(a, "titel"), text: sp(a, "text"), q: a.q || "e", src: a.src || [], at: a.at, neu: a.neu }));
  (N.jagd || []).forEach(j => L.JAGD_INFO.push(sp(j, "t")));
  /* Positionskorrekturen für Nachtrags-Einträge (aus der Positionsprüfung; positionen.js lädt vorher) */
  Object.entries(N.positionen || {}).forEach(([id, [x, y, g]]) => { const o = I[id] || L.ORTE.find(z => z.id === id); if (o) { o.p = [x, y]; o.g = g; } });
  L.PATCHES = (N.patches || []).map(p => ({ version: p.version, datum: p.datum, plattform: p.plattform, inhalt: sp(p, "inhalt"), src: p.src || [], neu: p.neu }))
    .sort((a, b) => String(b.datum).localeCompare(String(a.datum)));
})(window.LH_NACHTRAG);
